#include <stdio.h>
#include <string.h>

#define MAX_SIZE 100000

int main() {
    char target[4];
    gets(target);

    char stream[MAX_SIZE][4];
    int stream_size = 0;
    while(scanf("%s", stream[stream_size++])) {
        if(getchar() != ' ') break;
    }

    int i = 0;
    while(i < stream_size) {
        char* tag = stream[i++];

        char* tmp1 = stream[i++];
        char* tmp2 = stream[i++];

        char tmp[5] = {'\0'};
        strcat(tmp, tmp2);
        strcat(tmp, tmp1);

        int len;
        sscanf(tmp, "%x", &len);


        char res[len * 5];
        memset(res, '\0', len*5);

        for(int j = 0; j < len; j++) {
            strcat(res, stream[i++]);
            if(j < len - 1) {
                strcat(res, " ");
            }
        }

        if(strcmp(tag, target) == 0) {
            puts(res);
            return 0;
        }
    }

    return 0;
}
